For `LL/CON/SLA/BV-78-C`, I have a solution proposal which makes the test pass. I'm not 100% sure if this is how to do it:

(call to ll_length_max_get and use of MIN macro added)
```
hci.c:
static void le_set_data_len(struct net_buf *buf, struct net_buf **evt)
{
	struct bt_hci_cp_le_set_data_len *cmd = (void *)buf->data;
	struct bt_hci_rp_le_set_data_len *rp;
	u16_t tx_octets;
	u16_t tx_time;
	u16_t handle;
	u8_t status;

	u16_t max_tx_octets;
	u16_t max_tx_time;
	u16_t max_rx_octets;
	u16_t max_rx_time;

	ll_length_max_get(&max_tx_octets, &max_tx_time,
			  &max_rx_octets, &max_rx_time);

	handle    = sys_le16_to_cpu(cmd->handle);
	tx_octets = MIN(max_tx_octets, sys_le16_to_cpu(cmd->tx_octets));
	tx_time   = MIN(max_tx_time, sys_le16_to_cpu(cmd->tx_time));
	status    = ll_length_req_send(handle, tx_octets, tx_time);

	rp = hci_cmd_complete(evt, sizeof(*rp));
	rp->status = status;
	rp->handle = sys_cpu_to_le16(handle);
}
```
